/**
 * The library, in code — the destinations that exist, authored by hand.
 *
 * A destination is a LOOK and a VOICE (src/lib/tokens.ts) and the two are one
 * object, because one object is what both consumers read: the renderer takes
 * the look, the writer takes the voice, and neither can be given a destination
 * that is only half specified.
 *
 * ── Why these live in a module and not only in the database ──────────
 *
 * They will live in the database — `world.tokens` for the look and a versioned
 * `world_voice` row for the voice (db/004-destination-voice.sql). This module
 * is not a cache of that and must never become one. It is the CANONICAL,
 * REVIEWABLE text of a destination: a thing a curator and an engineer can read
 * in a diff, argue about in a pull request, and seed from. The same reasoning
 * as src/lib/quiz.ts — the vocabulary is data, and data that decides how the
 * product sounds deserves review, not an admin form and a prayer.
 *
 * Framework-free, like everything it imports. No React, no "server-only", so a
 * script can print a writer prompt without starting Next.
 *
 * ── The type, for now ────────────────────────────────────────────────
 *
 * Every destination uses the three faces src/app/fonts.css declares, because
 * that file is GENERATED by scripts/build-fonts.py and naming a fourth family
 * here would silently fall through to a system fallback. Giving a destination
 * its own face is a real change with a real cost: add it to build-fonts.py,
 * re-run the build, ship the woff2. Until then a destination differentiates on
 * palette and on voice, which is where the difference is felt anyway.
 */

import type { Destination, Theme } from "./tokens";
import type { ToneWeight } from "./voice";

/* ── THE ALLOCATION ────────────────────────────────────────────────────
 *
 * Twelve destinations, authored as ONE SET. Read this before adding a
 * fourteenth or re-tagging an existing one, because the value of the tone
 * question is not in any single destination's list — it is in the SPREAD.
 *
 * ── THE SEAM: WHICH LAYER OWNS THE ANSWER ────────────────────────────
 *
 * Two instruments can each name a destination, and this is the paragraph that
 * says how they compose. NOT YET IMPLEMENTED — see the gap at the end.
 *
 *   VOICE FILTERS, SOFTLY. The tiles are about her PEOPLE. A destination is
 *   removed only on actively NEGATIVE affinity — repulsion, not a weak match —
 *   and only when she tapped enough tiles for the signal to mean anything, and
 *   never below the survivor floor. Silence removes nothing.
 *
 *   STRUCTURE RANKS THE SURVIVORS. The matrix is about the EVENING: when it
 *   starts, who cooked, how it ends, how many. Log-odds over the facets in
 *   docs/destination-contrasts.md, nothing eliminated.
 *
 *   WITHIN AN EPSILON TIE, VOICE ORDERS IT. Two rows can be structurally
 *   identical and still be different houses.
 *
 *   THEY NEVER AVERAGE. The average of two axes is the destination that is
 *   middling on both, which is the compromise that is nobody's.
 *
 *   THE REVEAL IS TWO OR THREE, NOT ONE. Rank sharply, surface generously.
 *   The host chooses among the finalists and HER PICK IS LOGGED as first-class
 *   signal into the corrections pipeline — it is the only per-host data that
 *   will ever say whether the voice layer or the structural layer is
 *   mis-weighted. Framing is "the société has pulled these rooms for you":
 *   verdicts, plural. Never a browse, never a catalogue, never a filter she
 *   operates.
 *
 * ── SHE PICKS. THE REVEAL IS THE PICK ────────────────────────────────
 *
 * THE MAIN PATH, not a second surface. The engine ranks, two or three come back
 * as the société's verdicts, she taps one, and that is the assignment. There is
 * no confirmation step and no litigation of her choice.
 *
 * This SUPERSEDES the section headed "Settled — she does not pick the
 * destination" in docs/selection-spec.md, which is now annotated as such. Its
 * two arguments are answered rather than ignored, and the answer is that
 * ANSWERS SPLIT INTO TWO CLASSES that were previously treated as one:
 *
 *   TASTE ANSWERS — the tone tiles and the structural facets — are RANKING
 *   EVIDENCE. They are spent the moment the shortlist exists. A pick against
 *   the model's first choice is not a contradiction to be resolved: it is
 *   ground truth beating a posterior, which is the entire job of ground truth.
 *
 *   CONSTRAINT ANSWERS — dealbreakers, venue feasibility, platform, guest
 *   count, spend, and which deliverable she wants more of — SURVIVE the pick
 *   and govern assembly regardless of which room she chose. A costume
 *   dealbreaker still binds inside a destination she picked herself.
 *
 * So there is no such thing as a pick that "contradicts her answers", and no
 * mismatch to flag. The two classes never met.
 *
 * ── The picked destination is built as authored ──────────────────────
 *
 * NEVER BENT TOWARD HER QUIZ ANSWERS. She chose that room; she gets that room.
 * Bending an authored house toward the taste answers she just overruled would
 * reintroduce the averaging this block forbids, one layer down and out of
 * sight — a Dolomites softened toward a warm loud profile is neither house.
 * Constraints prune what can be issued inside it. Taste does not reshape it.
 *
 * ── What the pick is FOR ─────────────────────────────────────────────
 *
 * Logged as (application_id, predicted_ranking, picked_destination,
 * rank_of_pick) into the corrections pipeline. It is the only per-host datum
 * that will ever say whether the voice layer or the structural layer is
 * mis-weighted, and its value is entirely in the DIVERGENCE.
 *
 * SO IT IS NEVER USED TO RETRO-EDIT HER FACET PROFILE. Feeding the pick back
 * into the profile that predicted it destroys the measurement — the model would
 * be scored against a target it had just rewritten, and every calibration
 * number after that is self-congratulation. Protect the divergence.
 *
 * ── The no-pick state, stated so it cannot sneak back in ─────────────
 *
 * She may not tap. The state is PICK PENDING: the ranking is preserved
 * verbatim, nothing is assembled, and on timeout the TOP-RANKED destination
 * becomes the default.
 *
 * This is written down because it is the door "the engine always chooses"
 * walks back in through. An abandonment path that quietly re-runs anything, or
 * that loses the ranking and recomputes it later against a changed catalogue,
 * is the old architecture restored by accident. The default must be the stored
 * first rank and nothing else. `rank_of_pick` for a timed-out application is
 * recorded as a DEFAULT rather than as a pick of rank 1, or the calibration
 * data silently fills with agreements nobody made.
 *
 * ── Generosity at the reveal is not softness at the engine ───────────
 *
 * These are different surfaces and the distinction is load-bearing.
 * Discrimination is MEASURED AT THE ENGINE — src/lib/voice.test.ts still
 * asserts that distinct host profiles produce distinct winners and that the top
 * two are separated by a real margin. Those assertions do not relax because the
 * reveal shows three. A shortlist must never become the excuse for a mushy
 * matrix: if two rooms tie at the engine, that is a catalogue defect to fix,
 * not a choice to hand the host.
 *
 * It also does not reopen the question of whether SHE picks the destination.
 * docs/selection-spec.md settled that: "If she chooses from a shortlist, the
 * profile learns her self-image. If the curator chooses and she reacts, it
 * learns her taste." Two or three finalists with a logged pick is a reaction,
 * captured — not a menu.
 *
 * ── Why the tiebreak sentence is not optional ────────────────────────
 *
 * HAVANA and NEW ORLEANS. Structurally they are the same night — crowded,
 * cooked-for, evening, until morning — at distance 1 on the drafted matrix and
 * possibly 0 once it is corrected. A warm, loud, late group clears the voice
 * filter for BOTH, because a filter keeps and does not order. Structure is then
 * asked to sort two identical rows, ties, and the winner is iteration order:
 * the exact accident this block exists to prevent. With the tiebreak, the pair
 * is decided by "Nobody in the house is the target" against "Everybody is fair
 * game" — the right instrument, because evening-shape genuinely cannot tell
 * those two apart.
 *
 * ── Why the filter must be SOFT, which is an error-tolerance argument ─
 *
 * The rule is that one odd tap must never destroy the right answer, and it was
 * written about the ROBUST instrument. The tiles are the NOISY one: sparse, at
 * most seven of fifty-one, quiet by design, browsed, endorsement-suppressed and
 * optional. Giving the weak signal an unconditional veto and the strong signal
 * only ranking power is backwards. A host who taps three tiles slightly wrong
 * would eliminate her actual destination at the gate, and no amount of care
 * downstream can resurrect what the gate deleted.
 *
 * ── And why voice filters rather than the reverse ────────────────────
 *
 * This direction is FORCED, not merely preferred. The tile question is
 * skippable and `toneProfile([])` returns {} — a silent host makes no claim, so
 * she passes everything through and structure ranks the full field. Invert it —
 * structure filters, voice ranks — and a zero-tap host arrives at the ranking
 * stage with an empty ranker and no way to order anything. The OPTIONAL
 * instrument must be the layer that no-ops on silence.
 *
 * This is also consistent with precedent rather than novel. The earlier
 * decision in src/lib/selection/tone.ts — "Not a bigger weight, a TIER" —
 * settled voice against AESTHETIC. This settles voice against STRUCTURE. Same
 * shape, different pair. Anyone hunting for a contradiction between the two
 * will not find one.
 *
 * A note on what is NOT the argument: `facetOverlap` currently returns 0 for
 * every authored destination, because seed-destinations.mjs writes only voice
 * tags, so the ranking stage is inert and there is an empty socket the matrix
 * happens to fit. That is evidence about where the code has room, not about
 * which design is right. Sockets are cheaper to change than allocations, and
 * this decision would stand if the socket were full.
 *
 * ── The two numbers, and why they are not yet chosen ─────────────────
 *
 * SURVIVOR FLOOR is 3, and it is derived rather than picked: THE REVEAL SHOWS
 * TWO OR THREE, so below three survivors there is nothing to show and the
 * dither has nothing to dither. This used to be derived from "the curator is
 * shown three candidates" — there is no curator, the member picks, and the
 * reveal is the better derivation because it is the surface the number
 * actually serves. A tap pattern hostile to everything must degrade to
 * "structure decides", never to an empty room.
 *
 * MINIMUM TAPS is 3. The quiz permits one. A one-tap profile is a single
 * tone's facet vector, so a cosine against it measures that tone rather than a
 * voice; two is not much better. Three is the first count at which the
 * question is answering about a GROUP.
 *
 * REVEAL COUNT is 2-3. The curator prop this once leaned on is gone, and the
 * remaining arguments carry it alone. One is brittle for exactly the reason the tiebreak exists — at a
 * near-tie, a top-1 reveal is a coin-flip presented as a verdict. Larger sets
 * are worse, not better: the recommender literature finds long lists increase
 * choice difficulty and dissatisfaction against short ones, and a long list is
 * a browse, which is the thing this product is not.
 *
 * EPSILON IS NOT SET, and must not be guessed. Like the 0.20 tone threshold it
 * is a property of how densely the catalogue covers the space, and that
 * threshold was MEASURED (npm run check:tone-threshold) rather than chosen. Two
 * properties fix it: large enough that structurally identical rows — distance 0
 * and 1 — always reach the tiebreak, and small enough that a genuine structural
 * preference is never overturned by voice. Neither can be measured until the
 * structural scorer exists.
 *
 * ── THE GAP, STATED PLAINLY ──────────────────────────────────────────
 *
 * None of the above is implemented. Today src/lib/selection/destination.ts
 * filters HARD at tone >= 0.20 with no tap minimum and no survivor floor, ranks
 * on aesthetic facets that no authored destination carries, and has no
 * tiebreak. The three tests marked `todo` in src/lib/voice.test.ts are this
 * paragraph made mechanical, and they are the definition of done.
 *
 * ── The argument ─────────────────────────────────────────────────────
 *
 * A host taps a handful of the fifty-one tones in src/lib/voice.ts. A
 * destination is tagged in the same fifty-one. That join is the entire channel
 * between her and this library, and it is only worth having if her answer
 * CHANGES the answer. Twelve houses that are all dry and understated make the
 * question decorative: she taps, and every destination scores the same.
 *
 * So the set is allocated, not accumulated. Three properties are load-bearing,
 * and src/lib/voice.test.ts asserts all three:
 *
 *   1. EVERY ONE of the fifty-one tones is claimed by at least one
 *      destination. A tile that no destination answers to is a tile that
 *      wastes one of her seven taps.
 *   2. EVERY GROUP has destinations at BOTH ENDS. Someone performs
 *      (LAS VEGAS) and someone will not (WESTHAMPTON). Someone wants a
 *      seating plan (NEW YORK) and someone uses first names from the first
 *      minute (NANTUCKET). Someone explains nothing (WESTHAMPTON) and someone
 *      would rather you were told properly (DOLOMITES).
 *   3. NO TWO destinations resolve to nearly the same vector. Two houses that
 *      score the same against every host are one house with two palettes.
 *
 * ── The overlap rule ─────────────────────────────────────────────────
 *
 * Two destinations MAY share tones on one group. They must then differ on at
 * least two others. Overlap on one axis is texture; overlap on three is a
 * duplicate wearing a different name.
 *
 * Four destinations are slow, and that is fine, because each pays for it
 * elsewhere: CÔTE D'AZUR is slow and knowing and in view of a road; TAHITI is
 * slow and plain and generous; BIG SUR is slow and laconic and
 * self-deprecating; the DOLOMITES are slow and exact and told-properly. Three are warm — HAVANA
 * loud with it, CATSKILLS teasing with it, NANTUCKET nearly silent with it.
 *
 * ── The catalogue leads, not the gaps ────────────────────────────────
 *
 * Every tag below was taken from something the founder had already written in
 * docs/menus.md, docs/drinks.md or the plate rows in src/lib/library.ts. LAS
 * VEGAS builds a Caesar at the table and flames cherries with the lights down
 * (menu 19), so it is `makes_an_entrance` and `does_the_voice` because the
 * content says so, not because the slots were empty. Where a gap and the
 * catalogue disagreed, the catalogue won and the gap was filled somewhere it
 * was true instead.
 *
 * ── The table ────────────────────────────────────────────────────────
 *
 * Read down for a destination, across for who else claims a tone.
 *
 *   FUNNY
 *     deadpan            westhampton  · big-sur
 *     dry_aside          westhampton
 *     teasing            catskills    · nantucket
 *     in_jokes           catskills
 *     absurd             big-sur
 *     self_deprecating   big-sur      · portofino
 *     nothing_sacred     new-orleans  · westhampton
 *     good_natured       havana       · nantucket
 *   VOLUME
 *     all_at_once        new-orleans
 *     interrupts         new-orleans
 *     one_conversation   portofino    · catskills · dolomites
 *     across_the_room    las-vegas
 *     low_voices         westhampton
 *     laughs_first       havana
 *   CEREMONY
 *     toasts             new-york
 *     rises_to_greet     new-york
 *     seating_plan       new-york
 *     no_speeches        havana
 *     dressed_up         new-york     · las-vegas
 *     first_names        nantucket
 *   KINDNESS
 *     says_it_out_loud   havana
 *     nicknames          catskills
 *     asks_properly      havana
 *     warm_not_loud      nantucket    · portofino · tahiti
 *     compliments_plainly tahiti
 *     sentimental        catskills
 *   PRECISION
 *     exact_word         new-york     · portofino · westhampton · havana
 *     will_look_it_up    dolomites
 *     corrects_gently    new-york     · dolomites
 *     understated        westhampton
 *     roughly_eight      cote-dazur
 *     long_way_round     big-sur
 *   PACE
 *     unhurried          tahiti · westhampton · portofino · nantucket ·
 *                        big-sur · cote-dazur
 *     talks_fast         new-orleans
 *     arrives_late       tahiti
 *     lingers            havana       · cote-dazur · tahiti
 *     no_dead_air        new-orleans  · las-vegas
 *     comfortable_silence nantucket   · dolomites · big-sur · tahiti
 *   KNOWING
 *     leans_in           cote-dazur
 *     explains_nothing   westhampton
 *     straight_to_gossip new-orleans  · cote-dazur
 *     means_the_other_thing cote-dazur
 *     between_us         portofino
 *     spells_it_out      dolomites
 *   PERFORMANCE
 *     makes_an_entrance  las-vegas
 *     does_the_voice     las-vegas
 *     one_tells_it       cote-dazur
 *     nothing_by_halves  las-vegas
 *     never_performs     westhampton
 *     swears_fondly      new-orleans  · catskills
 *     impeccably_polite  dolomites
 *
 * ── The five poles ───────────────────────────────────────────────────
 *
 *   LAS VEGAS      performance. The opposite of Westhampton.
 *   NEW YORK       ceremony. Black tie, a seating plan, one toast.
 *   NANTUCKET      the other end of ceremony. Paper plates on purpose.
 *   NEW ORLEANS    pace and volume. Four conversations, none of them finished.
 *   CATSKILLS      family. Everyone has a name only this group uses.
 *
 * And the interior ones, distinctive without being extreme: CÔTE D'AZUR
 * knowing and oblique, PORTOFINO private and few,
 * DOLOMITES exact and told properly, BIG SUR laconic, TAHITI plain and
 * generous, HAVANA warm and late, WESTHAMPTON dry and disreputable.
 *
 * ── What is NOT tagged ───────────────────────────────────────────────
 *
 * Formality, address and humour mode, for every destination. The voice states
 * them outright and `statedVoiceFacets` derives them; saying a fact twice is
 * how two copies of it start to disagree. All twelve stated triples are
 * distinct, which is the cheapest structural guarantee that no two of these
 * houses are the same house.
 * ───────────────────────────────────────────────────────────────────── */

/**
 * WESTHAMPTON, 1976.
 *
 * The founder's tone target, and the first destination written end to end.
 * docs/copy-brief.md keeps it as the standard: "confident, specific, funny
 * without performing".
 */
