/**
 * WESTHAMPTON's voice, said in the tones a host is shown.
 *
 * ── WHY THE CATALOGUE IS TAGGED IN THE HOST'S VOCABULARY ─────────────
 *
 * The tones in src/lib/voice.ts are the whole width of the channel between a
 * host and this library. Describing a destination in anything richer — its own
 * private axes, tuned by hand — would leave the join between her handful of
 * taps and that description returning mush, because she was never given a way
 * to make most of those claims. So both sides are said in the same fifty words,
 * and the vocabulary is falsifiable: if a destination's voice cannot be written
 * in six to ten of them, the tones are wrong and get fixed.
 *
 * Every tag below points at a line in the voice above, not at an impression:
 *
 *   deadpan          "The house sleeps six and has slept nine."
 *   dry_aside        "Put the arrangement first. If there is a joke it is the
 *                     last four words."
 *   understated      "Two beats and stop; the third beat is where a line
 *                     starts performing."
 *   explains_nothing "Never explain a joke, and never explain the house."
 *   never_performs   "Never perform the period." "Never wink at the reader."
 *   low_voices       "A card left on the hall table by someone who has already
 *                     gone to bed."
 *   unhurried        "Drinks at seven, dinner when it suits us."
 *   exact_word       Hours in words, days by name, notices and not
 *                     announcements.
 *   nothing_sacred   "The upstairs bathroom door does not lock. It has never
 *                     mattered." Faint on purpose: the house is disreputable
 *                     about what happens in it and never crude in how it says
 *                     so, which is the difference between 0.35 and 1.
 *
 * Formality, address and humour mode are NOT tagged here. The voice above
 * states them outright — cordial, impersonal, dry — and they are derived from
 * it by `statedVoiceFacets`. Saying a fact twice is how two copies of it start
 * to disagree.
 */
export const WESTHAMPTON_1976_TONES: readonly ToneWeight[] = [
  { code: "deadpan", weight: 1 },
  { code: "understated", weight: 1 },
  { code: "explains_nothing", weight: 0.9 },
  { code: "never_performs", weight: 0.9 },
  { code: "dry_aside", weight: 0.8 },
  { code: "low_voices", weight: 0.7 },
  { code: "unhurried", weight: 0.6 },
  { code: "exact_word", weight: 0.5 },
  { code: "nothing_sacred", weight: 0.35 },
];

/**
 * HAVANA, 1957.
 *
 * The first destination the CATALOGUE asked for. Its food and its bar were
 * authored before it had a name — menus 28 and 29 in docs/menus.md, drinks 19
 * and 20 in docs/drinks.md — so the look and the voice below are written to
 * those and not the other way round. Read them first; everything here is an
 * answer to something specific in them.
 *
 * ── THE YEAR, AND THE RULE THAT OUTLIVED THE ARGUMENT AGAINST IT ─────
 *
 * This section was headed WHY THERE IS NO YEAR, and the argument was the
 * strongest in the file. Give this destination a decade, it said, and there is
 * only one decade anybody reaches for: 1950s Havana as an American playground —
 * the casinos, the linen suits, somebody else's country photographed at its
 * least free. That is kitsch and it is in poor taste. Havana was a place and an
 * HOUR where WESTHAMPTON is a place and a YEAR, and the hour dated nothing and
 * excluded nobody.
 *
 * The catalogue is now pinned to a period per destination, so the name is 1957.
 * READ THE REST OF THIS BLOCK BEFORE WRITING A WORD FOR IT.
 *
 * What was actually being refused was never the date. It was the sales pitch —
 * the last good year, the linen suits, a country served up as somebody's
 * playground. A date on a plate is a period the voice is written in. That
 * sentence is a posture the voice takes toward a place that was not its own,
 * and it stays forbidden: it is in `rejected`, in the room's own words, and it
 * is the reason the period rule exists rather than an exception to it.
 *
 * The hour survives everything the year did not touch. The founder's catalogue
 * names an evening with two halves — a long dinner party (28, 19) and A LATE
 * SUPPER AFTER DANCING (29, 20) — a structural fact almost nothing else in the
 * library has, and a fact about the clock rather than the calendar. Coffee at
 * every hour including after midnight, a bar that shakes rather than stirs, and
 * a table carried back against the wall in the middle of the evening. 1957
 * dates the register. The hour still runs the night.
 *
 * ── THE SECOND TRAP, AND THE RULE IT PRODUCED ────────────────────────
 *
 * WESTHAMPTON speaks as THE HOUSE. Havana speaks as a house too — a house in
 * Havana, in its own words — and the way that goes wrong is impersonation: an
 * accent set down on paper, a word spelled the way a foreigner hears it, an
 * exclamation borrowed to prove where we are. Real nouns are the opposite of
 * caricature. A courtyard, a fan, the Malecón, the ice, the last coffee are
 * facts; a performed accent is a costume. The rule is in `never`, in the
 * house's own words, exactly where WESTHAMPTON keeps its ban on anachronism.
 */
